
function cadenceLabel(c){return ({one_off:'One-off', '4_weeks':'Every 4 weeks','8_weeks':'Every 8 weeks',monthly:'Monthly',annual:'Annual'})[c]||c}
function renderCart(){const root=document.querySelector('[data-cart]');if(!root)return;let c=NF.getCart();let items=root.querySelector('[data-cart-items]'),sum=root.querySelector('[data-cart-summary]');if(!c.length){items.innerHTML='<div class="content-card"><h3>Your basket is empty.</h3><p>It is wonderfully organised, admittedly.</p><a class="button" href="/shop/">Go to the shop →</a></div>';sum.innerHTML='';return}let subtotal=0;items.innerHTML=c.map((x,i)=>{subtotal+=x.price*x.qty;return `<div class="cart-line"><img src="${x.image}" alt=""><div><b>${x.name}</b><div class="small">${cadenceLabel(x.cadence)}${x.flavour?` · ${x.flavour}`:''}</div><div class="small">${NF.money(x.price)} × ${x.qty}</div></div><div><button class="chip" data-remove="${i}">Remove</button></div></div>`}).join('');let ship=subtotal>=5000?0:395;sum.innerHTML=`<h3>Summary</h3><div class="summary-row"><span>Subtotal</span><b>${NF.money(subtotal)}</b></div><div class="summary-row"><span>Delivery today</span><b>${ship?NF.money(ship):'Free'}</b></div><div class="summary-row total"><span>Due today</span><span>${NF.money(subtotal+ship)}</span></div><p class="small">Recurring items keep their own cadence. Future charges are shown at checkout before commitment.</p><a class="button" href="/shop/checkout/">Checkout preview →</a>`;items.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{c.splice(Number(b.dataset.remove),1);NF.setCart(c);renderCart()})}
document.addEventListener('DOMContentLoaded',renderCart);
